INSERT INTO `content_items` (`id`, `tenant_id`, `type`, `title`, `title_ur`, `body`, `body_ur`, `sort`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'faq', 'Is the financing Shariah-compliant?', 'کیا فنانسنگ شریعہ کے مطابق ہے؟', 'Yes. Products use Murabaha, Ijarah or Musharakah structures approved by our Shariah advisor. No interest is charged; late payment amounts go to charity.', 'جی ہاں، تمام مصنوعات شریعہ بورڈ کی منظوری سے ہیں۔', 0, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
(2, 1, 'faq', 'Can I cancel after signing?', 'کیا دستخط کے بعد منسوخ کر سکتا ہوں؟', 'Yes – within the 24-hour cooling-off period you can cancel without any charge.', 'جی ہاں، 24 گھنٹے کے اندر بغیر کسی چارج کے۔', 1, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
(3, 1, 'faq', 'How do I pay instalments?', 'قسط کیسے ادا کریں؟', 'From your wallet, through Raast from any bank app, Merchant QR / IBAN alias, 1Bill at any bank, or Easypaisa / JazzCash.', 'والیٹ، راست، 1بل، ایزی پیسہ یا جاز کیش سے۔', 2, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
(4, 1, 'faq', 'Is my data safe?', 'کیا میرا ڈیٹا محفوظ ہے؟', 'Your data is stored in Pakistan, encrypted, and the app never accesses your contacts or gallery.', 'آپ کا ڈیٹا پاکستان میں محفوظ ہے۔', 3, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
(5, 1, 'banner', 'Own your motorbike from PKR 6,000/month*', 'صرف 6,000 روپے ماہانہ میں موٹر بائیک', '*Indicative. See KFS for final terms.', NULL, 0, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
(6, 1, 'notice', 'Branches closed on public holidays', NULL, 'Digital services remain available 24/7.', NULL, 0, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00'),
