INSERT INTO `products` (`id`, `tenant_id`, `parent_id`, `loan_category_id`, `code`, `name`, `name_ur`, `category`, `description`, `description_ur`, `icon`, `shariah_structure`, `shariah_board_approved`, `shariah_approval_ref`, `client_segment`, `is_staff_product`, `is_active`, `show_in_catalog`, `current_version_id`, `sort`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, NULL, 1, 'MBS', 'Motorbike Sahulat', 'موٹر بائیک سہولت', 'motorbike', 'Own a new motorbike through Murabaha: we buy the bike from the dealer and sell it to you at a disclosed profit.', 'موٹر بائیک سہولت – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-MBS-2026', 'individual', 0, 1, 1, 1, 0, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(2, 1, NULL, 1, 'ARK', 'Apna Rikshaw', 'اپنا رکشہ', 'rickshaw', 'Become your own boss with a loader or passenger rickshaw – asset-backed Murabaha financing.', 'اپنا رکشہ – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-ARK-2026', 'individual', 0, 1, 1, 2, 1, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(3, 1, NULL, 2, 'MLT', 'Mera Laptop', 'میرا لیپ ٹاپ', 'laptop', 'Laptops for students and freelancers with easy monthly instalments.', 'میرا لیپ ٹاپ – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-MLT-2026', 'individual', 0, 1, 1, 9, 2, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(4, 1, NULL, 1, 'SSC', 'Sohni Scooty', 'سوہنی سکوٹی', 'scooty', 'Scooty financing designed for working women and students.', 'سوہنی سکوٹی – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-SSC-2026', 'individual', 0, 1, 1, 4, 3, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(5, 1, NULL, 5, 'SLR', 'Solar Panel Financing', 'سولر پینل فنانسنگ', 'solar', 'Ijarah-based solar systems – cut your electricity bill while you pay rentals towards ownership.', 'سولر پینل فنانسنگ – شریعہ کے مطابق فنانسنگ', NULL, 'ijarah', 1, 'SB-DEMO-SLR-2026', 'individual', 0, 1, 1, 5, 4, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(6, 1, NULL, 2, 'HAP', 'Home Appliances', 'گھریلو سامان', 'home_appliances', 'Refrigerators, ACs, washing machines and sewing machines on Murabaha.', 'گھریلو سامان – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-HAP-2026', 'individual', 0, 1, 1, 6, 5, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(7, 1, NULL, 4, 'KBS', 'Karobar Sahulat', 'کاروبار سہولت', 'karobar_sme', 'Working-capital Musharakah partnership for shops and small enterprises. The 26% p.a. shown is the EXPECTED return under the agreed profit-sharing ratio (institution 60% / partner 40%); actual profit is shared at that ratio and losses in proportion to capital (see D-019 – structure pending Shariah board review).', 'کاروبار سہولت – شریعہ کے مطابق فنانسنگ', NULL, 'musharakah', 1, 'SB-DEMO-KBS-2026', 'individual', 0, 1, 1, 7, 6, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
(8, 1, NULL, 3, 'EDU', 'School Fee Financing', 'اسکول فیس فنانسنگ', 'school_fees', 'Your child\'s school fees are paid directly to the school – no cash is given to you. Repay over the school term (see D-020).', 'اسکول فیس فنانسنگ – شریعہ کے مطابق فنانسنگ', NULL, 'murabaha', 1, 'SB-DEMO-EDU-2026', 'individual', 0, 1, 1, 8, 7, '2025-09-26 04:00:00', '2025-09-26 04:00:00', NULL),
